// Math Studio runtime: stage routing, the Explore model, the practice runner, Apply, Reflect, evidence and save/resume.
// Content comes from the page's #ms-data (generated by scripts/generate-math-studio.mjs); logic lives in core.mjs.
import { checkTransfer, evidence, keywordEvidence, loadState, pickNext, predictItem, saveState, STAGE_NAMES, STAGES, transferTask, validate } from './core.mjs';
import { bi, esc, renderItem } from './items.mjs';

const L = JSON.parse(document.getElementById('ms-data').textContent);
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
// Storage can be blocked (private windows, managed Chromebooks): the studio still works, it just cannot remember.
const memory = new Map();
const storage = (() => {
  try { const k = '__ms'; localStorage.setItem(k, '1'); localStorage.removeItem(k); return localStorage; } catch {
    return { getItem: (k) => memory.get(k) ?? null, setItem: (k, v) => memory.set(k, v), removeItem: (k) => memory.delete(k) };
  }
})();
const state = loadState(storage, L.id);
const resumed = state.updatedAt > 0;
let saveTimer = 0;
const save = () => {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    const ok = saveState(storage, state);
    $('#ms-saved').innerHTML = ok && storage === localStorage ? bi('Saved on this device.', 'Guardado en este dispositivo.') : bi('Saving is off on this device; your work stays until you close the page.', 'No se puede guardar en este dispositivo; tu trabajo se queda hasta que cierres la página.');
    renderEvidence();
  }, 150);
};
addEventListener('pagehide', () => { clearTimeout(saveTimer); saveState(storage, state); });

// ---- Language ----
const LANG_KEY = 'ewl:math-studio:lang';
let lang = (() => { try { return localStorage.getItem(LANG_KEY) || 'en'; } catch { return 'en'; } })();
const applyLang = () => {
  document.body.classList.toggle('ms-es', lang === 'es');
  $('#ms-lang').setAttribute('aria-pressed', String(lang === 'es'));
};
$('#ms-lang').addEventListener('click', () => {
  lang = lang === 'es' ? 'en' : 'es';
  try { localStorage.setItem(LANG_KEY, lang); } catch { /* preference only */ }
  applyLang();
});
applyLang();

// ---- Stages ----
function setStage(stage, { focus = true } = {}) {
  if (!STAGES.includes(stage)) stage = 'explore';
  state.stage = stage;
  if (!state.visited.includes(stage)) state.visited.push(stage);
  $$('.ms-stage').forEach((s) => { s.hidden = s.dataset.stage !== stage; });
  $$('[data-stage-link]').forEach((a) => {
    if (a.dataset.stageLink === stage) a.setAttribute('aria-current', 'step'); else a.removeAttribute('aria-current');
    a.closest('li').dataset.visited = String(state.visited.includes(a.dataset.stageLink));
  });
  if (focus) $(`#h-${stage}`)?.focus({ preventScroll: true });
  if (focus) $('.ms-stagebar').scrollIntoView({ block: 'start', behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
  save();
}
const goto = (stage, focus = true) => {
  if (location.hash !== `#${stage}`) history.pushState(null, '', `#${stage}`);
  setStage(stage, { focus });
};
addEventListener('hashchange', () => setStage(location.hash.slice(1)));
document.addEventListener('click', (e) => {
  const link = e.target.closest('.ms-stagebar [data-stage-link]');
  if (link) { e.preventDefault(); goto(link.dataset.stageLink); return; }
  const a = e.target.closest('[data-goto]');
  if (!a) return;
  e.preventDefault();
  if (a.dataset.level) setLevel(a.dataset.level);
  goto(a.dataset.goto);
});

// ---- Explore: the lab's own model, mounted as a component ----
let model = null;
let mountModel, guidance;
// A lesson whose shared lab models a neighbour's mathematics has its own Explore model
// (data/math-studio/explore-overrides.json): either another lab model (explore.model) or one of these explorers.
const EXPLORERS = {
  'expression-parts': './parts.mjs',
  'decimal-align': './decimal-align.mjs',
  'prime-tree': './prime-tree.mjs',
  'properties': './properties.mjs',
  'like-terms': './like-terms.mjs',
  'fair-share': './fair-share.mjs',
  'stat-question': './stat-question.mjs',
  'composite': './composite.mjs',
};
const labModel = L.explore?.model || L.lab.model;
let custom = null, customMod = null;
async function loadModel() {
  const host = $('#ms-model');
  try {
    if (EXPLORERS[L.explore?.kind]) {
      customMod = await import(EXPLORERS[L.explore.kind]);
      custom = customMod.mount(host, L.explore, { onChange: (st) => { state.explore.custom = st; save(); } });
      const saved = state.explore.custom || state.explore.parts;
      if (saved) custom.set(saved);
      $('#ms-guide').innerHTML = `<strong>${esc(L.explore.guide[0])}</strong> ${esc(L.explore.guide[1])}`;
      return;
    }
    ({ mountModel, guidance } = await import('../../curriculum/learning-labs/shared/model.mjs'));
    const initial = state.explore.values?.length === labModel.values.length ? state.explore.values : labModel.values;
    model = mountModel(host, labModel, {
      initial: labModel.values,
      prefix: 'ms-model',
      lang: () => lang,
      onChange: (values) => { state.explore.values = values; save(); },
    });
    if (initial !== labModel.values) model.set(initial);
    const g = L.explore?.guide ? { show: L.explore.guide[0], tip: L.explore.guide[1] } : guidance(labModel);
    $('#ms-guide').innerHTML = `<strong>${esc(g.show)}</strong> ${esc(g.tip)}`;
  } catch (err) {
    host.innerHTML = `<p class="ms-warn">${bi('The model could not load. You can still use every other stage.', 'El modelo no se pudo cargar. Todavía puedes usar las demás etapas.')}</p>`;
    console.warn('Learning Lab model', err);
  }
}
function showHandoff() {
  const h = state.handoff, box = $('#ms-handoff');
  if (!h) { box.hidden = true; return; }
  box.hidden = false;
  box.innerHTML = `<p><strong>${bi('The model is set to your practice question’s numbers.', 'El modelo tiene los números de tu pregunta de práctica.')}</strong> ${bi('Change one quantity at a time and watch the readout. When you are ready, go back and revise your answer.', 'Cambia una cantidad a la vez y observa el resultado. Cuando estés listo, regresa y revisa tu respuesta.')}</p><button type="button" class="ms-btn" id="ms-return">${bi('Back to my question', 'Volver a mi pregunta')}</button>`;
  $('#ms-return').addEventListener('click', () => {
    state.handoff = null; showHandoff();
    goto(h.returnTo);
    requestAnimationFrame(() => $(`[data-item="${CSS.escape(h.problemId)}"]`)?.scrollIntoView({ block: 'center' }));
  });
}
/** Practice -> model, through the validated hand-off contract. */
function openModel(item, rec) {
  const level = levelOf(item.id);
  state.handoff = validate('handoff', {
    lessonId: L.id, conceptId: L.concept, modelId: labModel.kind, problemId: item.id, params: item.model.values,
    response: rec.response ?? null, misconception: rec.tags?.[0] || null, hintLevel: rec.hints, supports: ['model'], returnTo: 'practice', level,
  });
  model?.set(item.model.values);
  showHandoff();
  goto('explore');
}
/** Model -> practice: a question from the current settings, then a transfer question with no model. */
function makeQuestion() {
  if (custom) return makeCustomQuestions();
  if (!model) return;
  const out = $('#ms-test-out');
  const values = model.values;
  const item = predictItem(labModel, values, L.id);
  const round = (state.explore.round || 0) + 1;
  state.explore.round = round;
  const transfer = transferTask(labModel, L.id, round, 1);
  if (!item && !transfer) { out.innerHTML = `<p class="ms-muted">${bi('This model works best with the investigation questions above.', 'Este modelo funciona mejor con las preguntas de investigación.')}</p>`; return; }
  out.innerHTML = '<div class="ms-test__a"></div><div class="ms-test__b"></div>';
  const runTransfer = () => {
    if (!transfer) return;
    const t = { id: transfer.problemId, kind: 'num', prompt: transfer.prompt, answer: transfer.target, hints: [`Start from the relationship the model uses for the ${transfer.metric.toLowerCase()}.`, `Work backward: which value of “${transfer.field}” gives exactly ${transfer.target}?`], explanation: `Any value that makes the ${transfer.metric.toLowerCase()} equal ${transfer.target} is correct. You can test it in the model.` };
    renderItem($('.ms-test__b', out), t, {
      label: ['Transfer: a new problem, no model', 'Transferencia: un problema nuevo, sin el modelo'],
      check: (_it, text) => checkTransfer(labModel, transfer, text),
      rec: state.explore.checks[t.id],
      onChange: (rec) => { state.explore.checks[t.id] = rec; save(); },
    });
  };
  if (item) {
    renderItem($('.ms-test__a', out), item, {
      label: ['From your model', 'De tu modelo'],
      rec: state.explore.checks[item.id],
      onChange: (rec) => { state.explore.checks[item.id] = rec; if (rec.result && !$('.ms-test__b', out).innerHTML) runTransfer(); save(); },
    });
    if (state.explore.checks[item.id]?.result) runTransfer();
  } else runTransfer();
}
/** A lesson explorer's version: questions about what the student built, then a new problem with no model. */
async function makeCustomQuestions() {
  const out = $('#ms-test-out');
  const st = custom.state;
  const round = (state.explore.round || 0) + 1;
  state.explore.round = round;
  const queue = [...customMod.questions(st, L.id), customMod.transfer(st, round, L.id)];
  out.innerHTML = queue.map((_, i) => `<div class="ms-test__q" data-q="${i}"${i ? ' hidden' : ''}></div>`).join('');
  const fromModel = ['From your model', 'De tu modelo'];
  const transferLabel = ['Transfer: a new problem, no model', 'Transferencia: un problema nuevo, sin el modelo'];
  queue.forEach((item, i) => {
    const slot = $(`[data-q="${i}"]`, out);
    renderItem(slot, item, {
      label: i === queue.length - 1 ? transferLabel : fromModel,
      misconceptions: L.misconceptions,
      rec: state.explore.checks[item.id],
      onChange: (rec) => { state.explore.checks[item.id] = rec; if (rec.result) { const next = $(`[data-q="${i + 1}"]`, out); if (next) next.hidden = false; } save(); },
    });
    if (state.explore.checks[item.id]?.result) { const next = $(`[data-q="${i + 1}"]`, out); if (next) next.hidden = false; }
  });
}
$('#ms-make-question').addEventListener('click', makeQuestion);
for (const [id, key] of [['#ms-prediction', 'prediction'], ['#ms-notes', 'notes']]) {
  const el = $(id);
  el.value = state.explore[key] || '';
  el.addEventListener('input', () => { state.explore[key] = el.value; save(); });
}

// ---- Practice: Regular and Challenge in one runner ----
const counter = (done, total) => bi(`${done} of ${total} done`, `${done} de ${total} hechas`);
const levelOf = (id) => (L.practice.challenge.some((it) => it.id === id) ? 'challenge' : 'regular');
function setLevel(level) {
  state.practice.level = level;
  $$('.ms-levels [role=tab]').forEach((t) => t.setAttribute('aria-selected', String(t.dataset.level === level)));
  $('#ms-runner').setAttribute('aria-labelledby', `tab-${level}`);
  renderRunner();
  save();
}
function renderRunner() {
  const level = state.practice.level;
  const items = L.practice[level];
  const recs = state.practice.items;
  let current = items.find((it) => it.id === state.practice.current[level]) || items.find((it) => !recs[it.id]?.result) || items[0];
  state.practice.current[level] = current.id;
  const host = $('#ms-runner');
  const done = items.filter((it) => recs[it.id]?.result).length;
  host.innerHTML = `<div class="ms-dots" role="group" aria-label="${level === 'challenge' ? 'Challenge' : 'Regular'} questions">${items
    .map((it, i) => `<button type="button" class="ms-dot" data-jump="${esc(it.id)}" data-result="${recs[it.id]?.result || (recs[it.id]?.attempts ? 'trying' : 'new')}"${it.id === current.id ? ' aria-current="true"' : ''} aria-label="Question ${i + 1}${recs[it.id]?.result ? `, ${recs[it.id].result}` : ''}">${i + 1}</button>`)
    .join('')}<span class="ms-dots__count">${counter(done, items.length)}</span></div><div class="ms-card-host"></div>`;
  $$('[data-jump]', host).forEach((b) => b.addEventListener('click', () => { state.practice.current[level] = b.dataset.jump; renderRunner(); save(); }));
  const i = items.indexOf(current);
  renderItem($('.ms-card-host', host), current, {
    label: [`${level === 'challenge' ? 'Challenge' : 'Regular'} · Question ${i + 1} of ${items.length}`, `${level === 'challenge' ? 'Reto' : 'Regular'} · Pregunta ${i + 1} de ${items.length}`],
    rec: recs[current.id],
    misconceptions: L.misconceptions,
    onChange: (rec) => { recs[current.id] = rec; save(); updateDots(); },
    onModel: openModel,
    onNext: () => {
      const next = pickNext(items, recs, current);
      if (next) { state.practice.current[level] = next.id; renderRunner(); $('#ms-runner .ms-prompt')?.focus?.(); }
      else finishLevel(level);
      save();
    },
  });
}
function updateDots() {
  const recs = state.practice.items;
  $$('#ms-runner [data-jump]').forEach((b) => { b.dataset.result = recs[b.dataset.jump]?.result || (recs[b.dataset.jump]?.attempts ? 'trying' : 'new'); });
  const items = L.practice[state.practice.level];
  const c = $('#ms-runner .ms-dots__count');
  if (c) c.innerHTML = counter(items.filter((it) => recs[it.id]?.result).length, items.length);
}
function finishLevel(level) {
  const e = evidence(state, L)[level];
  $('.ms-card-host').innerHTML = `<div class="ms-done"><h3>${bi(level === 'challenge' ? 'Challenge complete' : 'Practice complete', level === 'challenge' ? 'Reto completo' : 'Práctica completa')}</h3><p>${bi(`${e.independent} on your own · ${e.supported} with support · ${e.revealed} from a worked example.`, `${e.independent} por tu cuenta · ${e.supported} con apoyo · ${e.revealed} con un ejemplo resuelto.`)}</p><div class="ms-row">${level === 'regular' ? `<button type="button" class="ms-btn" data-level="challenge" data-goto="practice">${bi('Try Challenge', 'Probar el reto')}</button>` : ''}<button type="button" class="ms-btn ms-btn--quiet" data-goto="apply">${bi('Go to Apply', 'Ir a Aplica')}</button></div></div>`;
}
$$('.ms-levels [role=tab]').forEach((t) => t.addEventListener('click', () => setLevel(t.dataset.level)));

// ---- Apply ----
function setupApply() {
  const sources = { word: L.apply.wordProblem, scenario: L.apply.scenario, reasoning: L.apply.reasoning, create: { sample: null } };
  $$('[data-apply-input]').forEach((ta) => {
    const key = ta.dataset.applyInput;
    ta.value = state.apply.responses[key] || '';
    ta.addEventListener('input', () => { state.apply.responses[key] = ta.value; save(); });
  });
  $$('[data-compare]').forEach((b) => b.addEventListener('click', () => {
    const key = b.dataset.compare, src = sources[key] || {}, out = $(`[data-compare-out="${key}"]`);
    const text = state.apply.responses[key] || '';
    out.hidden = false;
    if (text.trim().length < 15) { out.innerHTML = `<p class="ms-warn">${bi('Write your own reasoning first (a sentence or two), then compare.', 'Primero escribe tu propio razonamiento (una o dos oraciones) y luego compara.')}</p>`; return; }
    state.apply.compared[key] = true; save();
    const kw = src.keywords?.length ? keywordEvidence(text, src.keywords) : null;
    const kwLine = kw ? `<p>${bi(`Your explanation uses: ${kw.used.join(', ') || 'none of the key words yet'}.`, `Tu explicación usa: ${kw.used.join(', ') || 'todavía ninguna de las palabras clave'}.`)}${kw.missing.length ? ` ${bi(`Consider whether these belong in it: ${kw.missing.join(', ')}.`, `Piensa si estas deberían estar: ${kw.missing.join(', ')}.`)}` : ''}</p>` : '';
    const sample = src.sample ? `<p><strong>${bi('A sample answer:', 'Un ejemplo de respuesta:')}</strong> ${esc(src.sample)}</p>` : `<p>${bi('Check your plan: did you label every quantity, show the calculation, and explain why your plan works?', '¿Etiquetaste cada cantidad, mostraste el cálculo y explicaste por qué funciona tu plan?')}</p>`;
    out.innerHTML = `${kwLine}${sample}<p class="ms-muted">${bi('Revise your answer if the sample shows something you missed.', 'Revisa tu respuesta si el ejemplo muestra algo que no incluiste.')}</p>`;
  }));
}

// ---- Reflect ----
function renderReflect() {
  const host = $('#ms-reflect');
  const checks = L.reflect.checks || [];
  const ea = L.reflect.errorAnalysis;
  host.innerHTML = `${checks.map((_, i) => `<div class="ms-reflect-item" data-r="${i}"></div>`).join('')}${ea ? '<div class="ms-reflect-item" data-r="ea"></div>' : ''}
    <article class="ms-item"><p class="ms-eyebrow">${bi('Explain in writing', 'Explica por escrito')}</p><p class="ms-prompt">${bi(L.reflect.prompt || 'Explain the most important idea from this lesson using an example.', L.reflect.promptEs || (L.reflect.prompt ? '' : 'Explica la idea más importante de esta lección con un ejemplo.'))}</p>${L.reflect.frame ? `<p class="ms-frame">${bi(L.reflect.frame, L.reflect.frameEs)}</p>` : ''}<label class="ms-label" for="ms-writing">${bi('My explanation', 'Mi explicación')}</label><textarea id="ms-writing" rows="4"></textarea><div class="ms-feedback" id="ms-writing-fb" role="status" aria-live="polite"></div></article>`;
  const labels = [['On your own: exit check', 'Por tu cuenta: revisión de salida'], ['On your own: a new problem', 'Por tu cuenta: un problema nuevo']];
  checks.forEach((item, i) => renderItem($(`[data-r="${i}"]`, host), item, {
    label: labels[i] || ['On your own', 'Por tu cuenta'], independentOnly: true, misconceptions: L.misconceptions,
    rec: state.reflect.items[item.id],
    onChange: (rec) => { state.reflect.items[item.id] = rec; save(); },
  }));
  if (ea) renderItem($('[data-r="ea"]', host), { ...ea, id: 'reflect-error' }, {
    label: ['Error analysis', 'Análisis de errores'], independentOnly: true,
    rec: state.reflect.items['reflect-error'],
    onChange: (rec) => { state.reflect.items['reflect-error'] = rec; save(); },
  });
  const ta = $('#ms-writing');
  ta.value = state.reflect.writing || '';
  const fb = () => {
    const kw = keywordEvidence(ta.value, L.reflect.keywords || []);
    $('#ms-writing-fb').innerHTML = ta.value.trim().length < 15 ? '' : kw.used.length ? bi(`You used: ${kw.used.join(', ')}.`, `Usaste: ${kw.used.join(', ')}.`) : bi('Try to use a math word from this lesson in your explanation.', 'Intenta usar una palabra de matemáticas de esta lección.');
  };
  ta.addEventListener('input', () => { state.reflect.writing = ta.value; fb(); save(); });
  fb();
}

// ---- Evidence: participation, completion, supported and independent, kept apart ----
function renderEvidence() {
  const host = $('#ms-evidence');
  if (!host) return;
  const e = evidence(state, L);
  const row = (en, es, lv) => `<tr><th scope="row">${bi(en, es)}</th><td>${bi(`${lv.tried} of ${lv.total}`, `${lv.tried} de ${lv.total}`)}</td><td>${lv.independent}</td><td>${lv.supported}</td><td>${lv.revealed}</td><td>${lv.hints}</td><td>${lv.model}</td></tr>`;
  const next = e.reflect.independent === e.reflect.total && e.reflect.total
    ? ['You showed this on your own. Try the Challenge practice or the reasoning task in Apply.', 'Lo demostraste por tu cuenta. Prueba la práctica de Reto o la tarea de razonamiento en Aplica.']
    : e.regular.revealed || e.reflect.notYet ? ['Work on next: reread the worked examples in Understand, then try new Regular questions.', 'Para seguir: vuelve a leer los ejemplos resueltos en Comprende y luego prueba preguntas Regulares nuevas.']
      : ['Keep going: finish the Regular questions, then answer the Reflect checks on your own.', 'Sigue adelante: termina las preguntas Regulares y luego responde las revisiones de Reflexiona por tu cuenta.'];
  const th = (en, es) => `<th scope="col">${bi(en, es)}</th>`;
  host.innerHTML = `<h3>${bi('My evidence', 'Mi evidencia')}</h3>
    <ul class="ms-badges"><li data-on="${e.explored}">${bi('Explored', 'Exploré')}</li><li data-on="${e.understood}">${bi('Understand visited', 'Visité Comprende')}</li><li data-on="${e.applied > 0}">${bi(`Applied (${e.applied})`, `Apliqué (${e.applied})`)}</li><li data-on="${e.reflect.wrote}">${bi('Explained in writing', 'Expliqué por escrito')}</li></ul>
    <div class="ms-table-wrap"><table class="ms-table"><caption class="sr-only">Practice evidence</caption><thead><tr>${th('Practice', 'Práctica')}${th('Tried', 'Intenté')}${th('On my own', 'Por mi cuenta')}${th('With help', 'Con ayuda')}${th('Worked example', 'Ejemplo resuelto')}${th('Hints', 'Pistas')}${th('Used model', 'Usé el modelo')}</tr></thead><tbody>${row('Regular', 'Regular', e.regular)}${row('Challenge', 'Reto', e.challenge)}</tbody></table></div>
    <p>${bi(`Reflect: ${e.reflect.independent} of ${e.reflect.total} right on the first try · ${e.reflect.revised} revised to correct.`, `Reflexiona: ${e.reflect.independent} de ${e.reflect.total} correctas al primer intento · ${e.reflect.revised} corregidas al revisar.`)}</p>
    <p class="ms-next">${bi(...next)}</p>
    <div class="ms-row"><button type="button" class="ms-btn ms-btn--quiet" id="ms-download">${bi('Download my evidence', 'Descargar mi evidencia')}</button><button type="button" class="ms-btn ms-btn--link" id="ms-reset">${bi('Start this lesson over', 'Empezar esta lección de nuevo')}</button></div>
    <p class="ms-muted">${bi('Stored only on this device. No name is saved.', 'Se guarda solo en este dispositivo. No se guarda ningún nombre.')}</p>`;
  $('#ms-download').addEventListener('click', () => {
    const blob = new Blob([JSON.stringify({ lesson: L.id, title: L.title, savedAt: new Date().toISOString(), evidence: e }, null, 2)], { type: 'application/json' });
    const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: `math-studio-${L.id}-evidence.json` });
    a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });
  $('#ms-reset').addEventListener('click', (ev) => {
    const b = ev.currentTarget;
    if (b.dataset.armed !== '1') { b.dataset.armed = '1'; b.innerHTML = bi('Press again to erase this lesson’s saved work', 'Presiona otra vez para borrar el trabajo guardado de esta lección'); return; }
    try { storage.removeItem(`ewl:math-studio:v1:${L.id}`); } catch { /* nothing saved */ }
    location.replace(location.pathname + '#explore'); location.reload();
  });
}

// ---- Boot ----
if (resumed) {
  const box = $('#ms-resume');
  box.hidden = false;
  box.innerHTML = `<p>${bi('Welcome back. Your work in this lesson is saved.', 'Qué bueno verte de nuevo. Tu trabajo en esta lección está guardado.')}</p><button type="button" class="ms-btn" data-goto="${esc(state.stage)}">${bi(`Continue in ${STAGE_NAMES[state.stage][0]}`, `Continuar en ${STAGE_NAMES[state.stage][1]}`)}</button>`;
}
setupApply();
setLevel(state.practice.level);
renderReflect();
showHandoff();
setStage(STAGES.includes(location.hash.slice(1)) ? location.hash.slice(1) : 'explore', { focus: false });
loadModel();
